create extension if not exists pgcrypto;drop table if exists public.responses cascade;drop table if exists public.recipients cascade;drop table if exists public.suggestions cascade;drop table if exists public.page_heroes cascade;drop table if exists public.music_settings cascade;create table public.recipients(id uuid primary key default gen_random_uuid(),code text unique not null default encode(gen_random_bytes(6),'hex'),name text not null,active boolean not null default true,created_at timestamptz default now());create table public.responses(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references public.recipients(id) on delete cascade,selected_date date not null,preferred_time text not null,places text[] default '{}',foods text[] default '{}',custom_place text default '',custom_food text default '',notes text default '',created_at timestamptz default now());create table public.suggestions(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('place','food','date','time')),name text not null,emoji text default '✨',value text default '',remarks text default '',sort_order int default 0);create table public.page_heroes(page_key text primary key,emoji text not null,media_url text default '');create table public.music_settings(id int primary key default 1 check(id=1),enabled boolean not null default true,track_name text not null default 'Cute Music',music_url text not null default '/music/fassounds-cute-cute-music-549927.mp3',volume numeric not null default .5 check(volume between 0 and 1),updated_at timestamptz default now());insert into public.music_settings(id) values(1);alter table public.recipients enable row level security;alter table public.responses enable row level security;alter table public.suggestions enable row level security;alter table public.page_heroes enable row level security;alter table public.music_settings enable row level security;create policy "recipient read" on public.recipients for select to